class Solution {
public:
    int maximumNumberOfOnes(int width, int height,
                            int sideLength, int maxOnes) {
        vector<int> counts;
        for (int r = 0; r < sideLength; ++r) {
            for (int c = 0; c < sideLength; ++c) {
                int rows = (height - 1 - r) / sideLength + 1;
                int cols = (width - 1 - c) / sideLength + 1;
                counts.push_back(rows * cols);
            }
        }
        sort(counts.rbegin(), counts.rend());
        return accumulate(counts.begin(), counts.begin() + maxOnes, 0);
    }
};
